"""This file contains the Class with the functionality for the Login Screen page object"""

import interops.libraries.integrity.integrity_objects as integrity_objects

from interops.libraries.desktop.base_ui_page_object import BaseUIPageObject
import logging
import squishtest3 as sq
import interops.libraries.desktop.decorators as deco
from interops.libraries.squish_actions.constants import INTEGRITY_APP_NAME

logger = logging.getLogger(__name__)
class LoginScreen(BaseUIPageObject):
    application_name = INTEGRITY_APP_NAME

    #ToT=Yes
    #TODO: @deco.app_ctx_function() - seems to prevent login from happening...?
    def ready(self):
        try:
            #sq.waitForObjectExists(integrity_objects.login_Username_Edit,0)
            sq.waitForObjectExists(integrity_objects.login_Password_Edit,0)
            sq.waitForObjectExists(integrity_objects.login_OK_Button,0)
            sq.waitForObjectExists(integrity_objects.login_Shutdown_Button,0)
            sq.waitForObjectExists(integrity_objects.login_About_Button,0)
            return True
        except Exception as e:
            logger.info("Cannot find login screen "+str(e))
            return False

    #ToT=Yes
    @deco.app_ctx_function()
    def login_user (self,username, password):

        super(LoginScreen, self).mouseClick(integrity_objects.login_Username_Edit)
        super(LoginScreen, self).type(integrity_objects.login_Username_Edit, username)
        super(LoginScreen, self).mouseClick(integrity_objects.login_Password_Edit)
        super(LoginScreen, self).type(integrity_objects.login_Password_Edit, password)
        super(LoginScreen, self).click_button(integrity_objects.login_OK_Button)

        popup_OK = "{container={type='Pane'} text='OK' type='Button'}"
        try:
            sq.waitForObjectExists(popup_OK, 3000)
            super(LoginScreen, self).mouseClick(popup_OK)
        except LookupError:
            #TODO: do something useful if we get an exception?
            pass

    @deco.app_ctx_function()
    def shutdown (self):
        super(LoginScreen, self).mouseClick(integrity_objects.login_Shutdown_Button)
        super(LoginScreen, self).mouseClick(integrity_objects.yes_Button)
        #wait while shutting down
        sq.snooze(2)
        sq.waitForObjectExists(integrity_objects.park_MLC_label,900000)
        try:
            button = sq.findObject(integrity_objects.ignore_Button)
            enabled =sq.waitFor("button.enabled", 90000)
            sq.clickButton(sq.waitForObjectExists(integrity_objects.ignore_Button))
        except:
            pass
